@@ -1,11 +1,41 @@
 export type LatLng = { lat: number; lng: number };
+
+const EARTH_RADIUS_KM = 6371.0088;
+
+function assertLatLng(p: LatLng): void {
+  if (
+    !Number.isFinite(p.lat) ||
+    !Number.isFinite(p.lng) ||
+    p.lat < -90 ||
+    p.lat > 90 ||
+    p.lng < -180 ||
+    p.lng > 180
+  ) {
+    throw new RangeError(`invalid coordinates: lat=${p.lat}, lng=${p.lng}`);
+  }
+}

 /** Great-circle distance in kilometres. */
 export function haversineKm(a: LatLng, b: LatLng): number {
-  throw new Error("not implemented");
+  assertLatLng(a);
+  assertLatLng(b);
+  const toRad = (deg: number) => (deg * Math.PI) / 180;
+  const dLat = toRad(b.lat - a.lat);
+  const dLng = toRad(b.lng - a.lng);
+  const h =
+    Math.sin(dLat / 2) ** 2 + Math.cos(toRad(a.lat)) * Math.cos(toRad(b.lat)) * Math.sin(dLng / 2) ** 2;
+  // Clamp guards against floating-point values marginally above 1 for antipodal points.
+  return 2 * EARTH_RADIUS_KM * Math.asin(Math.min(1, Math.sqrt(h)));
 }

 /** Delivery zone "A" to "E" for a distance in kilometres. */
 export function zoneFor(distanceKm: number): "A" | "B" | "C" | "D" | "E" {
-  throw new Error("not implemented");
+  if (!Number.isFinite(distanceKm) || distanceKm < 0) {
+    throw new RangeError(`invalid distance: ${distanceKm}`);
+  }
+  if (distanceKm <= 25) return "A";
+  if (distanceKm <= 100) return "B";
+  if (distanceKm <= 400) return "C";
+  if (distanceKm <= 1000) return "D";
